function symSrc(x){ return String(x||'').split('|').map(p=>{ p=p.trim(); if(p[0]==='@'){ const k=p.indexOf(' '), id=k<0?p.slice(1):p.slice(1,k), rest=k<0?'':p.slice(k), o=IT[id]; return o?`<button class="lnk" data-goto="${id}">${o.s} ${o.n}</button>${rest}`:p; } return p==='A'?A:p; }).join(' '); }
function symRows(L){ const hv=L.some(r=>r[2]); const hd=hv?'<tr class="symh"><th>기호</th><td>뜻</td><td>값</td><td>출처</td></tr>':'';
  return hd+L.map(([t,d,v,x])=>`<tr><th><span class="mi" data-tex="${escA(t)}">${escA(texFallback(t))}</span></th><td>${d}</td>${hv?`<td class="symv">${v||''}</td><td class="syms">${symSrc(x)}</td>`:''}</tr>`).join(''); }
